import { describe, it, expect } from "vitest";
import {
  withTokenBudget,
  withGrant,
  decideGrant,
  grantPool,
  tokensLeft,
  chargeTokens,
  BudgetRefused,
  GRANT_POLICY,
} from "../src/core/budget.js";

const L = 50_000;
const reserve = Math.floor(L * GRANT_POLICY.operatorReserve);

describe("outside a run", () => {
  it("has no limits", () => {
    expect(tokensLeft("content")).toBe(Infinity);
    expect(grantPool()).toBe(Infinity);
  });
});

describe("decideGrant", () => {
  it("gives the agent's default share of the run when nothing is requested", async () => {
    await withTokenBudget(async () => {
      expect(decideGrant("content")).toEqual({ ok: true, tokens: Math.floor(L * GRANT_POLICY.defaults.content) });
    }, L);
  });

  it("gives what was requested when the pool has room", async () => {
    await withTokenBudget(async () => {
      expect(decideGrant("analytics", 7_000)).toEqual({ ok: true, tokens: 7_000 });
    }, L);
  });

  it("keeps the operator reserve out of the pool", async () => {
    await withTokenBudget(async () => {
      expect(grantPool()).toBe(L - reserve);
      chargeTokens("operator", 10_000);
      expect(grantPool()).toBe(L - 10_000 - reserve);
    }, L);
  });

  it("clips a request to the pool", async () => {
    await withTokenBudget(async () => {
      chargeTokens("operator", 25_000);
      const pool = L - 25_000 - reserve;
      expect(decideGrant("content", 30_000)).toEqual({ ok: true, tokens: pool });
    }, L);
  });

  it("refuses when the pool is below the agent's minimum, naming the numbers", async () => {
    await withTokenBudget(async () => {
      chargeTokens("operator", L - reserve - 1_000); // pool = 1000
      const d = decideGrant("content");
      expect(d.ok).toBe(false);
      if (!d.ok) expect(d.reason).toMatch(/content.*1000.*6000/);
    }, L);
  });

  it("refuses a request below the agent's minimum", async () => {
    await withTokenBudget(async () => {
      expect(decideGrant("content", 500).ok).toBe(false);
    }, L);
  });
});

describe("withGrant", () => {
  it("limits the job to its grant and counts its spend against the run", async () => {
    const { used } = await withTokenBudget(async () => {
      await withGrant("analytics", 5_000, async () => {
        expect(tokensLeft("analytics")).toBe(5_000);
        chargeTokens("analytics", 2_000);
        expect(tokensLeft("analytics")).toBe(3_000);
      });
    }, L);
    expect(used).toBe(2_000);
  });

  it("returns the unused part of a grant to the pool", async () => {
    await withTokenBudget(async () => {
      const r = await withGrant("analytics", 8_000, async () => chargeTokens("analytics", 2_000));
      expect(r).toMatchObject({ granted: 8_000, used: 2_000 });
      expect(grantPool()).toBe(L - 2_000 - reserve);
    }, L);
  });

  it("holds an active grant out of the pool so parallel jobs can't overcommit", async () => {
    await withTokenBudget(async () => {
      await withGrant("content", 20_000, async () => {
        expect(grantPool()).toBe(L - reserve - 20_000);
      });
    }, L);
  });

  it("charges nested helper calls (verify) to the same grant", async () => {
    await withTokenBudget(async () => {
      await withGrant("content", 10_000, async () => {
        chargeTokens("verify", 4_000);
        expect(tokensLeft("content")).toBe(6_000);
        expect(tokensLeft("verify")).toBe(6_000);
      });
    }, L);
  });

  it("throws BudgetRefused without running the job when the grant is refused", async () => {
    let ran = false;
    await withTokenBudget(async () => {
      chargeTokens("operator", L - reserve);
      await expect(withGrant("content", undefined, async () => { ran = true; })).rejects.toBeInstanceOf(BudgetRefused);
    }, L);
    expect(ran).toBe(false);
  });

  it("never lets the operator's own calls dip into a running grant", async () => {
    await withTokenBudget(async () => {
      await withGrant("content", 20_000, async () => {
        expect(tokensLeft("content")).toBe(20_000);
      });
      expect(tokensLeft("operator")).toBe(L);
    }, L);
  });
});

// Replay of live check-in 7 (2026-10-12, agent run a47c429e): per-call tokens from llm_calls.
// Under fixed shares Content was stopped with ~4171 left needing ~5833, while 18.7k of the run went unspent.
describe("regression: check-in 7 token starvation", () => {
  const beforeContent: [string, number][] = [
    ["operator", 1260], ["operator", 1526], ["analytics", 1517], ["analytics", 3651],
    ["operator", 2913], ["analytics", 1727], ["operator", 3523],
  ];
  const contentCalls = [1803, 3313, 5713];
  const nextContentCallNeeds = 5833;

  it("lets Content make its next call instead of stopping", async () => {
    await withTokenBudget(async () => {
      for (const [a, n] of beforeContent) chargeTokens(a, n);
      await withGrant("content", undefined, async () => {
        for (const n of contentCalls) chargeTokens("content", n);
        expect(tokensLeft("content")).toBeGreaterThanOrEqual(nextContentCallNeds);
      });
      // and the operator still has its reserve to write the summary
      expect(tokensLeft("operator")).toBeGreaterThanOrEqual(reserve);
    }, L);
  });
});

// Per-run token budget. One team run (an operator check-in plus every helper it
// calls) may use at most RUN_TOKEN_BUDGET tokens (input + output, incl. thinking).
//
// The operator spends from the run directly. When it hands a job to a helper, the
// job gets a grant from the pool: what the run has left, minus a reserve kept for
// the operator to finish, minus grants still running. A job whose grant would be
// below its minimum is refused before it starts. Unused grant goes back to the pool.
// The budget rides along the async call chain, so nested calls (e.g. verify inside
// content) draw from the same grant.

import { AsyncLocalStorage } from "async_hooks";
import { config } from "./config.js";

export const GRANT_POLICY = {
  // Share of the run kept back for the operator's own calls.
  operatorReserve: 0.2,
  // Grant when the operator doesn't ask for a size, as a share of the run.
  defaults: { analytics: 0.2, content: 0.4, support: 0.2 } as Record<string, number>,
  // Below this a job can't finish anything useful, so it isn't started.
  minimum: { analytics: 3_000, content: 6_000, support: 3_000 } as Record<string, number>,
};

export class TokenBudgetExceeded extends Error {}
export class BudgetRefused extends Error {}

interface Grant {
  agent: string;
  limit: number;
  used: number;
}

interface RunState {
  limit: number;
  used: number;
  byAgent: Map<string, number>;
  active: Set<Grant>;
}

interface Scope {
  run: RunState;
  grant?: Grant;
}

const store = new AsyncLocalStorage<Scope>();

export async function withTokenBudget<T>(
  fn: () => Promise<T>,
  limit = config.runTokenBudget
): Promise<{ result: T; used: number; limit: number; byAgent: Record<string, number> }> {
  const run: RunState = { limit, used: 0, byAgent: new Map(), active: new Set() };
  const result = await store.run({ run }, fn);
  return { result, used: run.used, limit, byAgent: Object.fromEntries(run.byAgent) };
}

/** Tokens free for new helper jobs right now (Infinity outside a run). */
export function grantPool(): number {
  const s = store.getStore();
  if (!s) return Infinity;
  const { run } = s;
  let held = 0;
  for (const g of run.active) held += Math.max(0, g.limit - g.used);
  return Math.max(0, run.limit - run.used - Math.floor(run.limit * GRANT_POLICY.operatorReserve) - held);
}

export type GrantDecision = { ok: true; tokens: number } | { ok: false; reason: string };

/** How many tokens a new job for this agent would get, or why it can't start. */
export function decideGrant(agent: string, requested?: number): GrantDecision {
  const s = store.getStore();
  if (!s) return { ok: true, tokens: Infinity };
  const pool = grantPool();
  const min = GRANT_POLICY.minimum[agent] ?? 0;
  const want = requested ?? Math.floor(s.run.limit * (GRANT_POLICY.defaults[agent] ?? 0));
  if (requested !== undefined && requested < min) {
    return { ok: false, reason: `${agent} needs at least ${min} tokens for a job; ${requested} was asked for` };
  }
  const tokens = Math.min(want, pool);
  if (tokens < min) {
    return { ok: false, reason: `${agent} not started: only ${pool} tokens free in this run, a job needs at least ${min}` };
  }
  return { ok: true, tokens };
}

/** Run a helper job inside its own grant. Throws BudgetRefused (without running fn) if no grant fits. */
export async function withGrant<T>(
  agent: string,
  requested: number | undefined,
  fn: () => Promise<T>
): Promise<{ result: T; granted: number; used: number }> {
  const s = store.getStore();
  if (!s) return { result: await fn(), granted: Infinity, used: 0 };
  const d = decideGrant(agent, requested);
  if (!d.ok) throw new BudgetRefused(d.reason);
  const grant: Grant = { agent, limit: d.tokens, used: 0 };
  s.run.active.add(grant);
  try {
    const result = await store.run({ run: s.run, grant }, fn);
    return { result, granted: grant.limit, used: grant.used };
  } finally {
    s.run.active.delete(grant);
  }
}

/** Tokens this agent may still spend: its grant if inside one, else the run (Infinity outside a run). */
export function tokensLeft(_agent: string): number {
  const s = store.getStore();
  if (!s) return Infinity;
  const runLeft = s.run.limit - s.run.used;
  return s.grant ? Math.min(runLeft, s.grant.limit - s.grant.used) : runLeft;
}

export function chargeTokens(agent: string, tokens: number): void {
  const s = store.getStore();
  if (!s) return;
  s.run.used += tokens;
  s.run.byAgent.set(agent, (s.run.byAgent.get(agent) ?? 0) + tokens);
  if (s.grant) s.grant.used += tokens;
}

/** Size of the budget the agent is working within, for messages. */
export function agentAllowance(_agent: string): number {
  const s = store.getStore();
  if (!s) return Infinity;
  return s.grant ? s.grant.limit : s.run.limit;
}

/** Tokens used so far in the current run (0 outside a run). */
export function tokensUsedInRun(): number {
  return store.getStore()?.run.used ?? 0;
}

